import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_IDENTIFIER = Pattern.compile("^[a-zA-Z_][a-zA-Z0-9_]*$");

    // Developer note: sortColumn is validated by frontend React component
    // before submission. Backend validation TODO for Q3 sprint.

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortColumn = req.getParameter("sort");
        String direction = req.getParameter("dir");
        String userId = req.getParameter("uid");

        // Validate date parameters using prepared statement params
        if (startDate == null || endDate == null) {
            resp.sendError(400, "Missing date range");
            return;
        }

        // Validate direction
        if (direction == null || (!direction.equals("ASC") && !direction.equals("DESC"))) {
            direction = "ASC";
        }

        // Validate reportType
        if (reportType == null || !SAFE_IDENTIFIER.matcher(reportType).matches()) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // sortColumn is used in ORDER BY - cannot be parameterized in JDBC
        // Frontend validates against allowed list, backend trusts frontend
        if (sortColumn == null) {
            sortColumn = "created_at";
        }

        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;

        try {
            conn = getConnection();

            // Build query - note sortColumn is concatenated (ORDER BY can't use ?)
            String query = "SELECT id, title, amount, created_at, status FROM reports_" 
                + reportType + " WHERE user_id = ? AND created_at BETWEEN ? AND ? ORDER BY " 
                + sortColumn + " " + direction;

            log.info("Executing report query for user: " + userId);

            stmt = conn.prepareStatement(query);
            stmt.setString(1, userId);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("{\"id\":%d,\"title\":\"%s\",\"amount\":\"%.2f\",\"date\":\"%s\",\"status\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getDouble("amount"),
                    rs.getString("created_at"),
                    rs.getString("status"));
                first = false;
            }
            out.print("\n]");

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS"));
    }

    private void closeQuietly(ResultSet rs, Statement stmt, Connection conn) {
        try { if (rs != null) rs.close(); } catch (Exception e) {}
        try { if (stmt != null) stmt.close(); } catch (Exception e) {}
        try { if (conn != null) conn.close(); } catch (Exception e) {}
    }
}
